{
  "items": [
    {
      "name": "LiouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "definition",
      "type": "ℝ → ℝ → Prop"
    },
    {
      "name": "Irrational.eventually_forall_le_dist_cast_div_of_denom_le",
      "module_name": "Mathlib.Topology.Instances.Irrational",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, Irrational x → ∀ (n : ℕ), ∀ᶠ (ε : ℝ) in nhds 0, ∀ k ≤ n, ∀ (m : ℤ), ε ≤ dist x (↑m / ↑k)"
    },
    {
      "name": "Liouville",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "definition",
      "type": "ℝ → Prop"
    },
    {
      "name": "Irrational.eventually_forall_le_dist_cast_rat_of_den_le",
      "module_name": "Mathlib.Topology.Instances.Irrational",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, Irrational x → ∀ (n : ℕ), ∀ᶠ (ε : ℝ) in nhds 0, ∀ (r : ℚ), r.den ≤ n → ε ≤ dist x ↑r"
    },
    {
      "name": "setOf_liouville_eq_irrational_inter_iInter_iUnion",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Residual",
      "kind": "theorem",
      "type": "{x | Liouville x} = {x | Irrational x} ∩ ⋂ n, ⋃ a, ⋃ b, ⋃ (_ : 1 < b), Metric.ball (↑a / ↑b) (1 / ↑b ^ n)"
    },
    {
      "name": "Irrational.eventually_forall_le_dist_cast_div",
      "module_name": "Mathlib.Topology.Instances.Irrational",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, Irrational x → ∀ (n : ℕ), ∀ᶠ (ε : ℝ) in nhds 0, ∀ (m : ℤ), ε ≤ dist x (↑m / ↑n)"
    },
    {
      "name": "Real.exists_rat_abs_sub_le_and_den_le",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ) {n : ℕ}, 0 < n → ∃ q, |ξ - ↑q| ≤ 1 / ((↑n + 1) * ↑q.den) ∧ q.den ≤ n"
    },
    {
      "name": "Real.infinite_rat_abs_sub_lt_one_div_den_sq_iff_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ), {q | |ξ - ↑q| < 1 / ↑q.den ^ 2}.Infinite ↔ Irrational ξ"
    }
  ]
}
